import sympy
from sympy.polys.domains import GF, ZZ, QQ

# Top-level setup for witness expressions
x, y = sympy.symbols('x y')

def conditions(witness):
    """
    Checks if the witness is a valid counterexample to the conjecture.
    The witness should be a polynomial ring R containing x and y.
    """
    # H_1: Let I = (x^2 + y^2 + 1) be the principal ideal generated by x^2 + y^2 + 1 in R.
    # We verify that the witness is a ring containing generators 'x' and 'y'.
    try:
        if hasattr(witness, 'gens') and hasattr(witness, 'domain'):
            gens_str = [str(g) for g in witness.gens]
            if 'x' in gens_str and 'y' in gens_str:
                h1_ok = True
            else:
                h1_ok = False
        else:
            h1_ok = False
    except Exception:
        h1_ok = False

    # neg_Q: The factor ring R/I is NOT an integral domain.
    # For a polynomial ring R over a domain, R/I is an integral domain 
    # if and only if the generator x^2 + y^2 + 1 is irreducible in R.
    # We check if it factors into more than one irreducible component (or a repeated component).
    try:
        if not h1_ok:
            neg_q_ok = False
        else:
            # Factor x^2 + y^2 + 1 over the domain of R
            coeff, factors = sympy.factor_list(x**2 + y**2 + 1, domain=witness.domain)
            
            # Sum the multiplicities of all non-constant factors
            total_mult = sum(mult for f, mult in factors)
            
            # It is an integral domain iff it is irreducible (total multiplicity == 1)
            is_domain = (total_mult == 1)
            
            # We want the negation of the conclusion
            neg_q_ok = not is_domain
    except Exception:
        neg_q_ok = False

    return [h1_ok, neg_q_ok]

CONDITION_LABELS = [
    "H_1: I = (x^2 + y^2 + 1) is an ideal in R",
    "¬Q: R/I is not an integral domain"
]

N_HYP = 1
NEG_Q_INDEX = 1